// Extract and format incoming security anomaly details
const data = $input.first().json;

const timestamp = data.timestamp || new Date().toISOString();
const formattedDate = new Date(timestamp).toLocaleString('en-US', {
  timeZoneName: 'short',
  hour12: true
});

const confidence = data.confidence_score 
  ? `${Math.round(data.confidence_score * 100)}%` 
  : '95%';

return [{
  json: {
    anomaly_type: (data.anomaly_type || 'tailgating').toUpperCase(),
    camera_id: data.camera_id || 'Gate_04_Demo',
    confidence_score: data.confidence_score || 0.95,
    confidence_percent: confidence,
    timestamp: timestamp,
    formatted_time: formattedDate,
    snapshot_url: data.snapshot_url || 'https://via.placeholder.com/640x480?text=No+Snapshot+Available',
    severity: 'HIGH',
    alert_title: '🚨 SECURITY ALERT: TAILGATING DETECTED'
  }
}];

